#include "game/world_generation/caves/cave_field.h"
#include <iostream>
using namespace altaria::caves;
static Query one(const Chamber&c){Network n;n.valid=true;n.chambers={c};auto ptr=std::make_shared<IndexedNetwork>(n);Query q;q.owners.push_back(ptr);q.primitives.push_back({ptr.get(),0});q.bins=ptr->bins;return q;}
int main(){PlanSettings cfg;cfg.floor=-448;cfg.ceiling=320;cfg.isolated_chance=1;cfg.entrance_chance=1;cfg.infernal_chance=1;cfg.archetypes={{"mod:small",0,3,{6,5,6},{6,5,6},4},{"mod:giant",1,1,{100,25,100},{100,25,100},2},{"mod:tall",1,1,{6,100,6},{6,100,6},8}};Planner p(5,0,cfg,[](float,float){return 110.f;});auto own=p.region({-2,1}),other=p.region({-2,2});const Chamber*a=nullptr,*b=nullptr;for(auto&c:own.chambers)if(c.id==9279416757114523918ULL)a=&c;for(auto&c:other.chambers)if(c.id==3819296908948384346ULL)b=&c;if(!a||!b){std::cout<<"CASE_NOT_PRESENT own="<<bool(a)<<" other="<<bool(b)<<'\n';return 2;}auto qa=one(*a),qb=one(*b);for(int z=510;z<=530;z++){Point v{-367,19,float(z)};auto x=sample(qa,v,110,cfg.floor,cfg.roof_margin,.75f),y=sample(qb,v,110,cfg.floor,cfg.roof_margin,.75f);if(x.carved&&y.carved){std::cout<<"VOXEL_OVERLAP_DESPITE_MAX_SHRINK seed=5 isolated_id="<<a->id<<" neighbor_id="<<b->id<<" voxel="<<v[0]<<","<<v[1]<<","<<v[2]<<" distances="<<x.distance<<","<<y.distance<<" detail=+.75\n";return 1;}}std::cout<<"NO_OVERLAP\n";return 0;}
